js.text:

function grid$sysuserinfo(f){
  this.constructor(f);
}
grid$sysuserinfo.prototype = new DirEvent();
grid$sysuserinfo.prototype.afterInit = function(){
	var p = this._dir;
}
grid$sysuserinfo.prototype.beforeButtonGridClick = function(id){
  if (id == 'permission') {
    var p = this._dir;
    p.wait(true);

    var m = new Memvars();
    p.grequest(0, 'permission', 'GetRow', 'user_id', funResult);
    return false;
  }
  return true
}
function funResult(p, d){
  d = new DataRow(d);
  if(d.val('result') == '')
    $.createDir(false, { controller: 'permissionUser', backdropclick: false, folder: "Filter", dirViewType: "Dialog", parent: p });   
  else
    $.alert($.msg.get(d.val('result')));
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
